CH = dict(num=8, title="A Journey through States of Water", theme="States of water, evaporation, condensation, water cycle",
 intro="Aavi and Thirav, looking at ice in their lemonade, ask whether ice and water are the same thing. Through puddles, steel plates, tumblers of ice water and clay pots they discover that water exists as **solid, liquid and gas**, changes state on heating or cooling, **evaporates** and **condenses**, and travels through the **water cycle**. The chapter also trains the habit of observing, questioning, reasoning and testing.",
 big_questions=["Are ice, water and vapour the same substance?", "Where does water go when it disappears, and where do droplets on a cold glass come from?", "What affects the speed of evaporation?", "How do clouds and rain form?"],
 blocks=[
 ("h2", "8.0 Ice and Water Are One Substance"),
 ("p", "Activity 8.1: an ice cube left in a cup turns into water, so **ice and water are two forms (states) of the same substance**. Their behaviour differs — water flows and splashes, ice does not."),
 ("h2", "8.1 Investigating Water's Disappearing Act"),
 ("ul", ["Puddles on the playground and water on washed utensils disappear. Aavi suggests water **seeps** into the ground/surface; Thirav disagrees.", "Activity 8.2: a tablespoon of water on a **steel plate** does not seep through, yet vanishes — it has turned into **water vapour**, the gaseous state of water.", "Steam from water sprinkled on a hot dosa pan is actually water vapour (invisible); visible 'steam' is tiny water droplets formed from some vapour."]),
 ("note", "DEFINITION", "**Evaporation** is the conversion of water (liquid) into water vapour. It takes place **continuously, even at room temperature** (wet clothes drying, mopped floors, sweat, hand sanitiser disappearing)."),
 ("p", "Puddles disappear by evaporation — and partly by seeping into soil (both)."),
 ("h2", "8.2 Another Mystery: Droplets on the Glass"),
 ("p", "Activity 8.3: cold water with ice in a glass tumbler forms **water droplets on the outer surface** after a few minutes; small drops merge into bigger ones. Possible reasons: (a) ice came out, (b) water seeped out through glass, (c) water vapour from air condensed. Reasoning: water level did not fall, so seeping is unlikely."),
 ("note", "DEFINITION", "**Condensation** is the conversion of water vapour into liquid water when vapour in air touches a **cold surface** (dew on plants in the morning; drops on the inside of a lid covering boiling water)."),
 ("p", "Activity 8.4: a tumbler of ice water covered with a steel plate is weighed every 5 minutes for 30 minutes — the **mass increases**, because water vapour from the air condenses on the tumbler. Marking the water level shows it **does not go down**, proving no seepage; extra water is from condensation. The amount of water vapour in air is called **humidity**."),
 ("h2", "8.3 States of Water"),
 ("table", ["Property", "Ice (solid)", "Water (liquid)", "Water vapour (gas)"],
  [["Shape", "Fixed; keeps its shape in any container", "No fixed shape; takes shape of container", "No fixed shape"],
   ["Flow", "Does not flow", "Flows", "Spreads"],
   ["Spreading", "Does not spread", "Spreads on a surface; volume stays constant", "Spreads throughout available space"],
   ["Visibility", "Visible", "Visible", "Invisible, present in air even at room temperature"]]),
 ("ul", ["Other substances also show three states: wax, oil, ghee.", "Solids: stones, wood, glass. Liquids: milk, oil. Gases: oxygen, carbon dioxide.", "The smell of cooking food reaches us because **gases spread** through air."]),
 ("h2", "8.4 Changing the States of Water"),
 ("table", ["Process", "Change", "Condition"],
  [["**Melting**", "Solid → liquid (ice → water)", "Supply heat"],
   ["**Freezing**", "Liquid → solid (water → ice)", "Cool, e.g. in a freezer"],
   ["**Evaporation**", "Liquid → gas (vapour)", "Heating or at room temperature"],
   ["**Condensation**", "Gas → liquid", "Cooling / contact with a cold surface"]]),
 ("ul", ["Candle wax melts on heating and solidifies on cooling; coconut oil solidifies in winter.", "Atmospheric Water Generators collect drinking water by cooling humid air so vapour condenses."]),
 ("h2", "8.5 Faster or Slower Evaporation"),
 ("p", "In investigations change **one condition** and keep others the same."),
 ("table", ["Factor", "Effect on evaporation", "Everyday example"],
  [["**Exposed area** (plate vs bottle cap)", "More area → **faster**", "Spread clothes out to dry"],
   ["**Temperature / sunlight**", "Hotter / sunny → **faster**", "Clothes dry quickly on hot days"],
   ["**Air movement (wind)**", "More wind → **faster**", "Clothes dry faster on a windy day or under a fan"],
   ["**Humidity**", "High humidity → **slower**", "Clothes dry slowly on rainy days"]]),
 ("h2", "8.6 Cooling Effect"),
 ("ul", ["Water in a **matka** (earthen pot) is cold because water seeps through tiny pores and **evaporates from the surface, cooling the water** inside. A stainless steel pot has no pores. The **surahi** works the same way.", "Other examples: sprinkling water on a floor or roof in summer, sweat evaporating, sanitiser feeling cool, sitting under a fan (moving air helps sweat evaporate).", "**Pot-in-pot cooler** (Activity 8.9): small earthen pot inside a larger one, gap filled with sand, sand kept moist, covered with a lid or wet jute sack; evaporation from wet sand cools the inner pot in 4–5 hours and keeps vegetables and fruits fresh for days."]),
 ("note", "REMEMBER", "**Evaporation causes cooling.**"),
 ("h2", "8.7 How Do Clouds Give Us Rain?"),
 ("steps", [("Evaporation", "Water from oceans and the Earth's surface becomes water vapour, which is lighter than air and rises."),
  ("Cooling", "Higher up the air gets cooler and cooler."),
  ("Condensation", "Vapour condenses into tiny droplets around **dust particles**; these floating droplets form **clouds**."),
  ("Growth", "Many droplets join to form bigger drops."),
  ("Precipitation", "Heavy drops fall as **rain**, or as **hail or snow** under special conditions.")]),
 ("p", "Activity 8.10: in a bottle with a little water, squeeze and release repeatedly. Haze (cloud) appears much more clearly when a **burnt piece of newspaper** is added — it provides dust particles around which vapour condenses. (Handle burning paper carefully.)"),
 ("h3", "The water cycle"),
 ("note", "DEFINITION", "The continuous circulation of water between Earth's surface and atmosphere — evaporation from ocean/land, condensation to clouds, rain/snow/hail, flow through rivers, lakes and groundwater back to oceans — is the **water cycle**."),
 ("p", "Only a small portion of Earth's water is fit for use by plants, animals and humans; most is in oceans. With rising population, demand grows and shortages occur, so **use water wisely and keep water bodies unpolluted**."),
 ("h2", "8.8 Likely Exam Questions"),
 ("qa", [("Are ice, water and water vapour different substances?", "No, they are three states of the same substance, water."),
  ("Define evaporation and give two examples.", "Conversion of liquid water into vapour; drying clothes, disappearing puddles."),
  ("Define condensation. Give an example.", "Water vapour turning to liquid on cooling; drops on a cold glass, dew."),
  ("Why do droplets form on the outside of a glass of cold water?", "Water vapour in air condenses on its cold surface; water does not seep through glass."),
  ("What is humidity?", "The amount of water vapour present in air."),
  ("Compare solid, liquid and gas states of water.", "Solid has fixed shape; liquid takes container's shape and flows; gas spreads in all available space."),
  ("What factors affect the rate of evaporation?", "Exposed area, temperature, wind and humidity."),
  ("Why do clothes dry slowly on rainy days?", "High humidity makes evaporation slow."),
  ("Why is water in a matka cool?", "Water seeping through pores evaporates and cools the water."),
  ("How are clouds formed?", "Vapour rises, cools and condenses around dust particles to form tiny droplets."),
  ("What is the water cycle?", "Continuous circulation of water between Earth and atmosphere through evaporation, condensation and precipitation."),
  ("How can a hot two-wheeler seat be cooled?", "Sprinkle water on it so evaporation cools it, or keep it in shade.")]),
 ],
 takeaways=["Water exists as ice (solid), water (liquid) and vapour (gas).",
  "Evaporation: liquid → vapour; condensation: vapour → liquid; melting and freezing link solid and liquid.",
  "Evaporation is faster with larger area, higher temperature and wind, and slower with high humidity.",
  "Evaporation causes cooling (matka, pot-in-pot cooler, sweat).",
  "Clouds form by condensation on dust particles; rain, hail or snow follow.",
  "The water cycle circulates water; conserve it and avoid pollution."])
